    "old_post_name" varchar(64), "new_post_name" varchar(64),
    "old_post_level" varchar(64), "new_post_level" varchar(64),
    "old_work_address" varchar(128), "new_work_address" varchar(128),
    "old_leader_employee_id" bigint, "new_leader_employee_id" bigint,
    "old_leader_employee_name" varchar(64), "new_leader_employee_name" varchar(64),
    "probation" int, "effect_time" timestamp, "remark" varchar(255),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

